<?php require __DIR__.'/bootstrap.php'; $u=require_client();
if($_SERVER['REQUEST_METHOD']==='POST'){ $subject=trim($_POST['subject']??'');$message=trim($_POST['message']??'');if($subject&&$message){$pdo->prepare('INSERT INTO support_tickets(user_id,subject,message) VALUES(?,?,?)')->execute([$u['id'],$subject,$message]);flash('ok','Seu chamado foi enviado. A equipe responderá por aqui.');}header('Location: support.php');exit; }
$ok=flash('ok');$q=$pdo->prepare('SELECT * FROM support_tickets WHERE user_id=? ORDER BY id DESC');$q->execute([$u['id']]);$tickets=$q->fetchAll();?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Meu suporte — Arena de Aço</title><link rel="stylesheet" href="assets/app.css"></head><body class="anime"><?php nav($u)?><main class="client-area"><p class="eyebrow">CENTRAL DO ASSINANTE</p><h1>Suporte</h1><p class="muted">Abra um chamado e acompanhe a resposta da equipe da Arena de Aço.</p><?php if($ok):?><p class="alert ok"><?=e($ok)?></p><?php endif?><div class="client-grid"><section class="panel"><h2>Novo chamado</h2><form method="post"><label>Assunto<input required name="subject" maxlength="180" placeholder="Ex.: problema no acesso"></label><label>Como podemos ajudar?<textarea required name="message" placeholder="Descreva sua dúvida ou problema"></textarea></label><button class="redbtn">Enviar ao suporte →</button></form></section><section class="panel"><h2>Meus chamados</h2><?php foreach($tickets as $t):$r=$pdo->prepare('SELECT r.*,u.name FROM support_replies r JOIN users u ON u.id=r.author_id WHERE ticket_id=? ORDER BY r.id ASC');$r->execute([$t['id']]);?><article class="ticket"><div><b>#<?=$t['id']?> · <?=e($t['subject'])?></b><span class="status <?=e($t['status'])?>"><?=e($t['status'])?></span></div><p><?=nl2br(e($t['message']))?></p><?php foreach($r as $reply):?><div class="reply"><small>Equipe Arena de Aço · <?=date('d/m/Y H:i',strtotime($reply['created_at']))?></small><p><?=nl2br(e($reply['message']))?></p></div><?php endforeach?></article><?php endforeach;if(!$tickets):?><p class="muted">Você ainda não possui chamados.</p><?php endif?></section></div></main></body></html>
